# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from typing import List, Tuple

from hourglass.models import Shift

Row = Tuple[str, int, int]


def _validate(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to total")
    if any(not s.worker.strip() for s in shifts):
        raise ValueError("shift has a blank worker name")


def _totals(shifts: List[Shift]) -> List[Row]:
    """(worker, count, minutes), first-seen order."""
    found = {}
    for shift in shifts:
        n, m = found.get(shift.worker, (0, 0))
        minutes = shift.span.minutes
        found[shift.worker] = (n + 1, m + minutes)
    return [(w, n, m) for w, (n, m) in found.items()]


# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, most minutes worked first."""
    _validate(shifts)
    rows = sorted(
        _totals(shifts),
        key=lambda r: (-r[2], r[0])
    )
    return [
        f"{w}: {n} shifts, {m / 60:.1f} hours"
        for w, n, m in rows
    ]

